import{_ as s,o as a,c,a3 as i}from"./chunks/framework.MGD2uYU7.js";const r=JSON.parse('{"title":"SC-24 — Đăng ký phiên đấu giá & nộp cọc","description":"","frontmatter":{"title":"SC-24 — Đăng ký phiên đấu giá & nộp cọc"},"headers":[],"relativePath":"wireframes/user/sc-24-dang-ky-phien-coc.md","filePath":"wireframes/user/sc-24-dang-ky-phien-coc.md","lastUpdated":1791606799000}'),l={name:"wireframes/user/sc-24-dang-ky-phien-coc.md"};function t(p,n,h,d,e,o){return a(),c("div",null,[...n[0]||(n[0]=[i('<h1 id="sc-24-—-đang-ky-tham-gia-phien-đat-coc" tabindex="-1">SC-24 — Đăng ký tham gia phiên + đặt cọc <a class="header-anchor" href="#sc-24-—-đang-ky-tham-gia-phien-đat-coc" aria-label="Permalink to &quot;SC-24 — Đăng ký tham gia phiên + đặt cọc&quot;">​</a></h1><p><span class="wf-badge danger">ƯU TIÊN RẤT CAO</span> <span class="wf-badge info">Route: /dau-gia/toi</span> <span class="wf-badge muted">Nguồn: docs/05 §3 SC-24 · docs/03 UC-07 · docs/08 BR-AU / BR-PAY · docs/06 §5</span></p><p><strong>Ai xem màn này</strong>: Thành viên đã KYC APPROVED muốn tham gia một phiên (chưa đăng ký) · người đang ở trạng thái <code>PENDING_DEPOSIT</code> (chờ tiền về / chờ ADMIN xác nhận) · người đã <code>ACTIVE</code> xem lại thông tin tham gia · người bị chặn (đóng đăng ký 410, mất quyền 403, chưa KYC 403). <strong>Cảm xúc cần thiết kế</strong>: đây là lần đầu nhiều người chuyển <strong>90 triệu đồng thật</strong> cho một sàn web. Cảm xúc phải là &quot;mình biết chính xác số tiền, vì sao là số đó, tiền đi đâu về đâu, bao lâu thì xong&quot; — không thúc giục, không đồng hồ nhấp nháy tạo áp lực, không chữ nhỏ. <strong>Ví dụ số dùng trong bản vẽ</strong>: phiên <code>DGA-2026-0001</code> (<code>auc_01J9X3K8M2</code>) · căn <code>CT2-A18.05</code> · dự án NOXH <code>HP-380</code> · giá khởi điểm <code>1.800.000.000 ₫</code> · bước giá <code>18.000.000 ₫</code> (1%) · <strong>cọc 5% = <code>90.000.000 ₫</code></strong> (mức tối thiểu 10.000.000 ₫) · mở phiên <code>16/10/2026 08:00</code> · đóng đăng ký <code>15/10/2026 08:00</code> (GMT+7) · người tham gia <code>TV-7F2A</code>.</p><h2 id="_1-desktop-—-trang-đang-ky-quy-che-→-coc-→-kenh" tabindex="-1">1. Desktop — trang đăng ký (quy chế → cọc → kênh) <a class="header-anchor" href="#_1-desktop-—-trang-đang-ky-quy-che-→-coc-→-kenh" aria-label="Permalink to &quot;1. Desktop — trang đăng ký (quy chế → cọc → kênh)&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/dau-gia/toi</span></div><div class="wf-body"><div class="wf-header"><span class="wf-logo">AnPhuc</span><span class="wf-nav"><span>Mua nhà</span><span class="active">Đấu giá</span><span>Bảng gói</span><span>Hướng dẫn</span></span><span class="wf-header-actions"><span class="wf-bell">🔔<span class="count">2</span></span><span class="wf-avatar">NA</span></span></div><div class="wf-container"><div class="wf-breadcrumb">Đấu giá › <b>Đăng ký tham gia phiên DGA-2026-0001</b></div><div class="wf-steps"><span class="wf-step done">1 · Đọc quy chế ✓</span><span class="wf-step active">2 · Tiền cọc</span><span class="wf-step">3 · Kênh thanh toán</span></div><div class="wf-row" style="align-items:flex-start;"><div class="wf-grow wf-col"><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-row between middle"><span class="wf-title">Bước 1 · Quy chế tham gia đấu giá <span class="wf-callout">1</span></span><span class="wf-badge ok">✓ đã đọc &amp; đồng ý</span></div><span class="wf-small">Bạn đã cuộn hết quy chế và tick đồng ý lúc 10/10/2026 14:02 (GMT+7). Nội dung quy chế không đổi sau khi bạn đồng ý.</span><span class="wf-btn ghost sm">Xem lại quy chế</span></div></div><div class="wf-card" style="border-width:2px;border-color:var(--wf-line-strong);"><div class="pad wf-col" style="gap:10px;"><span class="wf-title">Bước 2 · Tiền cọc phải nộp <span class="wf-callout">2</span></span><div class="wf-row between"><span class="wf-text">Giá khởi điểm của phiên</span><span class="wf-money">1.800.000.000 ₫</span></div><div class="wf-row between"><span class="wf-text">Tỷ lệ cọc theo quy chế phiên</span><span class="wf-money">5%</span></div><div class="wf-row between"><span class="wf-text">Tính ra: 1.800.000.000 × 5% (làm tròn xuống)</span><span class="wf-money">90.000.000 ₫</span></div><div class="wf-row between"><span class="wf-text">Mức cọc tối thiểu theo quy định</span><span class="wf-money">10.000.000 ₫</span></div><div class="wf-row between"><span class="wf-small wf-muted">Áp mức tối thiểu? Không — 90.000.000 ₫ đã cao hơn 10.000.000 ₫</span><span class="wf-small wf-muted">—</span></div><div class="wf-row between" style="border-top:2px solid var(--wf-ink);padding-top:8px;"><span class="wf-strong">Số tiền bạn chuyển</span><span class="wf-money lg">90.000.000 ₫</span></div><div class="wf-note" style="margin:0;">Chuyển <b>đúng</b> 90.000.000 ₫ — lệch số tiền hệ thống không tự ghi nhận cọc (đối soát bắt buộc khớp). <span class="wf-callout">3</span></div></div></div><div class="wf-card"><div class="pad wf-col" style="gap:10px;"><span class="wf-title">Bước 3 · Chọn kênh nộp cọc <span class="wf-callout">4</span></span><div class="wf-col" style="gap:6px;"><span class="wf-radio checked">VNPay — thanh toán online, hệ thống ghi nhận cọc ngay khi giao dịch thành công</span><span class="wf-radio">Chuyển khoản thủ công — nhận thông tin bill, chờ ADMIN xác nhận (mục tiêu ≤ 2 giờ làm việc)</span></div><span class="wf-btn primary lg block">TẠO GIAO DỊCH &amp; CHUYỂN ĐẾN VNPay — 90.000.000 ₫</span><span class="wf-small wf-center">Link thanh toán có hiệu lực <b>6 giờ</b>; hết hiệu lực thì tạo lại, không giới hạn số lần trước giờ đóng đăng ký.</span></div></div></div><div style="width:320px;flex:none;" class="wf-col"><div class="wf-card"><div class="wf-img" style="min-height:130px;border-radius:0;border:none;border-bottom:1px solid var(--wf-line);"><span>ẢNH CĂN HỘ (từ tin đăng)</span></div><div class="pad wf-col" style="gap:8px;"><span class="wf-badge info">SẮP MỞ — CÒN NHẬN ĐĂNG KÝ</span><span class="wf-title">Căn CT2-A18.05 — NOXH HP-380</span><span class="wf-text">72 m² · 2 PN · 1 WC · tầng 18 · Sổ hồng</span><div class="wf-row between"><span class="wf-text">Giá khởi điểm</span><span class="wf-money">1.800.000.000 ₫</span></div><div class="wf-row between"><span class="wf-text">Bước giá</span><span class="wf-money">+18.000.000 ₫</span></div><div class="wf-row between"><span class="wf-text">Mở phiên</span><span>16/10/2026 08:00</span></div><span class="wf-small wf-accent">Xem chi tiết phiên → SC-05/SC-06</span></div></div><div class="wf-card" style="border-width:2px;border-color:var(--wf-line-strong);"><div class="pad wf-col" style="gap:8px;"><div class="wf-center"><span class="wf-small">ĐÓNG ĐĂNG KÝ SAU <span class="wf-callout">5</span></span><br><span class="wf-countdown sm">4 ngày 21:18:07</span></div><span class="wf-small wf-center">Đến 15/10/2026 08:00 (GMT+7) — trước giờ mở phiên 24 giờ</span><div class="wf-row between"><span class="wf-text">Đã đăng ký</span><span class="wf-strong">7 người</span></div></div></div><div class="wf-note">Nếu trúng: cọc được <b>trừ vào</b> số tiền phải trả. Nếu thua: hoàn <b>100%</b> trong 3 ngày làm việc. Nếu trúng mà không thanh toán trong 24 giờ: <b>mất cọc</b>. <span class="wf-callout">6</span></div></div></div></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/03 UC-07 · docs/08 BR-AU/BR-PAY · docs/05 §5)</div><ol><li><span class="num">1</span><span><b>Quy chế là bước bắt buộc</b>: modal phải cuộn hết + tick mới bật nút đồng ý (mục 2). Sau khi đồng ý, bước 1 thu gọn thành dòng xác nhận có mốc giờ — để user biết mình đã chấp nhận lúc nào, và xem lại được. Nội dung quy chế lấy từ cấu hình/BR của phiên, <b>không tự suy đoán điều khoản</b>. <span class="ref">UC-07 MF-1</span></span></li><li><span class="num">2</span><span><b>Breakdown từng dòng, không số gộp</b>: hiện cả công thức (giá khởi điểm × 5%, làm tròn xuống) và mức tối thiểu 10.000.000 ₫ để user thấy số 90.000.000 ₫ từ đâu ra. Cọc = <code>floor(openingPrice × depositPercent/100)</code>, min 10.000.000; số liệu do server trả về (<code>depositAmount</code>) — FE không tự tính để hiển thị chính. <span class="ref">BR-AU-06</span> <span class="ref">docs/05 §1.6</span></span></li><li><span class="num">3</span><span>Cảnh báo &quot;chuyển đúng số tiền&quot; là thật: đối soát bắt buộc <code>amount</code> khớp <code>depositAmount</code>, lệch ⇒ <code>RECON_FAILED</code> và hệ thống <b>không tự ghi nhận cọc</b>. Nói trước để user không chuyển thiếu/thừa rồi phải gọi CS. <span class="ref">BR-PAY-01</span></span></li><li><span class="num">4</span><span><b>Chọn kênh</b> → <code>POST /auctions/{id}/registrations</code> tạo registration <code>PENDING_DEPOSIT</code>, rồi <code>POST /payments/intents</code> (<code>purpose=deposit</code>, <code>refId=agr_…</code>): VNPay trả <code>checkoutUrl</code> → redirect; MANUAL_TRANSFER trả <code>checkoutUrl: null</code> + khối thông tin bill (mục 4). Nút ở trạng thái loading disabled khi đang tạo (chống double-submit; gửi kèm Idempotency-Key). <span class="ref">docs/06 §4.3/§4.5</span> <span class="ref">FR-PAY-01/03</span></span></li><li><span class="num">5</span><span>Đồng hồ &quot;đóng đăng ký&quot; dùng offset giờ server (header <code>X-Server-Time</code>), không tin đồng hồ máy khách; về 0 → trang chuyển sang trạng thái 410 (mục 7), không cho tạo giao dịch nữa. <span class="ref">BR-AU-04</span> <span class="ref">BR-AU-21</span></span></li><li><span class="num">6</span><span><b>Ba kết cục của tiền cọc</b> phải hiện ngay trên trang đăng ký, trước khi user bấm thanh toán — không giấu ở trang FAQ. Số thật, hạn thật. <span class="ref">BR-PAY-05</span> <span class="ref">BR-PAY-06</span> <span class="ref">BR-AU-15</span></span></li><li><span class="num">7</span><span>Điều kiện đăng ký được kiểm <b>trước</b> khi mở form: KYC APPROVED, tài khoản ACTIVE, quyền đấu giá GRANTED, không phải chủ căn này, chưa có registration cho phiên. Thiếu điều kiện nào → panel giải thích điều đó (mục 7), không hiện form rồi mới báo lỗi. <span class="ref">BR-AU-05</span></span></li></ol></div><h2 id="_2-quy-che-modal-—-bat-buoc-cuon-het-tick-moi-đuoc-đong-y" tabindex="-1">2. Quy chế modal — bắt buộc cuộn hết + tick mới được đồng ý <a class="header-anchor" href="#_2-quy-che-modal-—-bat-buoc-cuon-het-tick-moi-đuoc-đong-y" aria-label="Permalink to &quot;2. Quy chế modal — bắt buộc cuộn hết + tick mới được đồng ý&quot;">​</a></h2><div class="wf"><div class="wf-row" style="gap:20px;flex-wrap:wrap;justify-content:center;"><div style="flex:1;min-width:320px;"><span class="wf-state-label">A · CHƯA CUỘN HẾT (NÚT KHÓA)</span><div class="wf-modal-overlay"><div class="wf-modal"><div class="head">Quy chế tham gia đấu giá — phiên DGA-2026-0001</div><span class="wf-small wf-muted">Bắt buộc đọc hết nội dung bên dưới. Bạn phải cuộn tới cuối.</span><div class="wf-card flat" style="margin:10px 0;max-height:220px;overflow:hidden;"><div class="pad wf-col" style="gap:8px;"><div class="wf-lines"><span class="w-90"></span><span class="w-100"></span><span class="w-75"></span><span class="w-90"></span><span class="w-60"></span><span class="w-100"></span><span class="w-40"></span></div><span class="wf-small wf-strong">TÓM TẮT CÁC ĐIỂM CHÍNH (đầy đủ trong khung cuộn)</span><span class="wf-small">· Cọc <b>90.000.000 ₫</b> (5% giá khởi điểm, tối thiểu 10.000.000 ₫) — phải nộp trước 15/10/2026 08:00.</span><span class="wf-small">· Giá đã gửi <b>không rút lại, không sửa</b>; mỗi giá cách giá hiện tại ít nhất 18.000.000 ₫.</span><span class="wf-small">· Có giá trong 60 giây cuối → phiên tự kéo dài thêm 60 giây, không giới hạn số lần.</span><span class="wf-small">· Người tham gia chỉ hiện bí danh dạng <b>TV-XXXX</b>.</span><span class="wf-small">· Trúng giá: thanh toán phần còn lại trong <b>24 giờ</b>; quá hạn <b>mất cọc</b> và bị tạm ngưng quyền đấu giá.</span><span class="wf-small">· Không trúng: hoàn cọc 100% trong <b>3 ngày làm việc</b> về tài khoản đã nộp.</span><span class="wf-small wf-muted">… nội dung còn lại (điều khoản, quy trình, liên hệ) …</span></div></div><span class="wf-small wf-warn-text">⏳ Chưa đọc hết — còn 62% nội dung <span class="wf-callout">8</span></span><div class="wf-col" style="gap:6px;margin-top:8px;"><span class="wf-checkbox wf-muted">Tôi đã đọc và đồng ý với Quy chế tham gia đấu giá</span><span class="wf-btn disabled block">ĐỒNG Ý &amp; TIẾP TỤC</span><span class="wf-btn ghost block">Đóng</span></div></div></div></div><div style="flex:1;min-width:320px;"><span class="wf-state-label">B · ĐÃ CUỘN HẾT + TICK (NÚT BẬT)</span><div class="wf-modal-overlay"><div class="wf-modal"><div class="head">Quy chế tham gia đấu giá — phiên DGA-2026-0001</div><div class="wf-card flat" style="margin:10px 0;border-color:var(--wf-ok);"><div class="pad"><span class="wf-small wf-ok-text">✓ Bạn đã đọc hết nội dung — 100%</span><div class="wf-lines" style="margin-top:6px;"><span class="w-100"></span><span class="w-75"></span><span class="w-40"></span></div></div></div><div class="wf-col" style="gap:6px;"><span class="wf-checkbox checked">Tôi đã đọc và đồng ý với Quy chế tham gia đấu giá</span><span class="wf-btn primary block">ĐỒNG Ý &amp; TIẾP TỤC <span class="wf-callout">9</span></span><span class="wf-btn ghost block">Đóng</span></div><span class="wf-small wf-center" style="margin-top:8px;">Đồng ý = hệ thống ghi nhận thời điểm + phiên bản quy chế (audit)</span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">8</span><span><b>Scroll-to-bottom thật</b>: chỉ bật tick khi khung nội dung đã cuộn tới đáy (đo <code>scrollTop + clientHeight ≥ scrollHeight − 8px</code>). Checkbox trước đó disabled + mờ; nếu user cố tick bằng phím tắt khi chưa cuộn → vẫn chặn và cuộn về đầu phần chưa đọc. Không dùng timer &quot;giả vờ đã đọc&quot;, không cho tắt bằng click nền hay phím Esc (chỉ nút Đóng). <span class="ref">UC-07 MF-1</span></span></li><li><span class="num">9</span><span>Đồng ý → gọi <code>POST /auctions/{id}/registrations</code> → 201 <code>PENDING_DEPOSIT</code> + <code>depositAmount</code> + <code>regDeadline</code>. Đóng modal, trang chuyển sang bước 2/3 (mục 1). Lỗi: 409 <code>DUPLICATE_REGISTRATION</code> → bỏ modal, hiện thẳng trạng thái đăng ký đang có; 410 <code>AUCTION_REG_CLOSED</code> → banner mục 7. <span class="ref">docs/06 §4.3</span> <span class="ref">BR-AU-05</span></span></li><li><span class="num">10</span><span>Nội dung quy chế là <b>văn bản do Pháp chế/Ops duyệt</b> (docs/05 §8 ghi rõ đây là hạng mục blocking MS2) — designer chỉ thiết kế khung đọc, không tự viết điều khoản; phần tóm tắt bullet phải khớp văn bản đầy đủ. <span class="ref">docs/05 §8</span></span></li></ol></div><h2 id="_3-kenh-vnpay-amp-kenh-chuyen-khoan-thu-cong-bill-nut-sao-chep" tabindex="-1">3. Kênh VNPay &amp; kênh chuyển khoản thủ công (bill + nút sao chép) <a class="header-anchor" href="#_3-kenh-vnpay-amp-kenh-chuyen-khoan-thu-cong-bill-nut-sao-chep" aria-label="Permalink to &quot;3. Kênh VNPay &amp;amp; kênh chuyển khoản thủ công (bill + nút sao chép)&quot;">​</a></h2><div class="wf"><div class="wf-grid"><div class="wf-col"><span class="wf-state-label">KÊNH 1 · VNPAY (REDIRECT GATEWAY)</span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-row between middle"><span class="wf-radio checked">VNPay</span><span class="wf-badge info">ghi nhận ngay</span></div><div class="wf-row between"><span class="wf-text">Số tiền</span><span class="wf-money">90.000.000 ₫</span></div><div class="wf-row between"><span class="wf-text">Mục đích</span><span>Cọc tham gia phiên DGA-2026-0001</span></div><div class="wf-row between"><span class="wf-text">Mã giao dịch</span><span class="wf-trace">pay_01J9ZK2M4Q</span></div><div class="wf-row between"><span class="wf-text">Link hết hiệu lực</span><span>10/10/2026 20:05 (GMT+7) — sau 6 giờ</span></div><span class="wf-btn primary block">CHUYỂN ĐẾN VNPay</span><span class="wf-small">Sau khi quay lại trang, hệ thống <b>kiểm tra trạng thái giao dịch mỗi 5 giây</b> cho tới khi có kết quả (tối đa 5 phút) — đừng tắt tab. <span class="wf-callout">11</span></span><div class="wf-toast info" style="margin:0;">⏳ Đang chờ kết quả từ VNPay… lần kiểm tra kế tiếp sau 5 giây · <u>Kiểm tra ngay</u></div><span class="wf-small wf-muted">Gateway không phản hồi? Chuyển sang kênh thủ công bên phải — cọc vẫn được tính nếu nộp trước giờ đóng đăng ký.</span></div></div></div><div class="wf-col"><span class="wf-state-label">KÊNH 2 · CHUYỂN KHOẢN THỦ CÔNG (BILL)</span><div class="wf-card" style="border-width:2px;border-color:var(--wf-line-strong);"><div class="pad wf-col" style="gap:8px;"><div class="wf-row between middle"><span class="wf-radio">Chuyển khoản thủ công</span><span class="wf-badge warn">chờ ADMIN xác nhận</span></div><span class="wf-small wf-strong">THÔNG TIN CHUYỂN KHOẢN — sao chép từng dòng</span><div class="wf-card flat"><div class="pad wf-row between middle"><div class="wf-col" style="gap:2px;"><span class="wf-small">Ngân hàng</span><span class="wf-strong">[bankName từ API]</span></div><span class="wf-btn sm">Sao chép</span></div></div><div class="wf-card flat"><div class="pad wf-row between middle"><div class="wf-col" style="gap:2px;"><span class="wf-small">Số tài khoản</span><span class="wf-strong">[accountNo từ API]</span></div><span class="wf-btn sm">Sao chép</span></div></div><div class="wf-card flat"><div class="pad wf-row between middle"><div class="wf-col" style="gap:2px;"><span class="wf-small">Chủ tài khoản</span><span class="wf-strong">[accountName từ API]</span></div><span class="wf-btn sm">Sao chép</span></div></div><div class="wf-card flat"><div class="pad wf-row between middle"><div class="wf-col" style="gap:2px;"><span class="wf-small">Số tiền (đúng từng đồng)</span><span class="wf-money">90.000.000 ₫</span></div><span class="wf-btn sm">Sao chép</span></div></div><div class="wf-card flat" style="border-color:var(--wf-accent);background:var(--wf-accent-soft);"><div class="pad wf-col" style="gap:6px;"><span class="wf-small wf-strong">NỘI DUNG CHUYỂN KHOẢN (bắt buộc đúng)</span><span class="wf-money lg">ANPHUC pay_01J9ZK2M4Q</span><span class="wf-small">Mẫu: <code>ANPHUC &lt;paymentId&gt;</code> — mỗi giao dịch một mã riêng, <b>không dùng lại</b> mã của lần khác. <span class="wf-callout danger">12</span></span><span class="wf-btn primary sm block">Sao chép nội dung</span></div></div><div class="wf-toast ok" style="margin:0;">✓ Đã sao chép nội dung chuyển khoản</div><span class="wf-small">Chuyển xong: ADMIN đối chiếu nội dung + số tiền rồi xác nhận, mục tiêu <b>≤ 2 giờ làm việc</b>; sát giờ đóng đăng ký sẽ báo &quot;chờ duyệt&quot;. <span class="wf-callout">13</span></span><span class="wf-btn block">Tôi đã chuyển khoản — xem trạng thái</span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">11</span><span><b>Poll 5 giây</b> sau khi quay lại từ gateway (<code>GET /payments/{id}</code> / <code>GET /auctions/{id}/registrations/me</code>): INITIATED/PROCESSING → giữ panel chờ; SUCCESS → chuyển sang trạng thái ACTIVE (mục 5); FAILED/EXPIRED → toast đỏ + nút &quot;Tạo giao dịch mới&quot;. Webhook có thể đến trước redirect, nên <b>luôn hỏi lại server</b>, không suy ra kết quả từ URL trả về. <span class="ref">docs/05 §3 SC-24</span> <span class="ref">UC-07 AF-2</span> <span class="ref">BR-PAY-03</span></span></li><li><span class="num">12</span><span>Nội dung bill là <b>chìa khóa đối soát</b>: ADMIN chỉ xác nhận khi nội dung khớp <code>ANPHUC &lt;paymentId&gt;</code> <b>và</b> số tiền khớp. Sai nội dung/sai tiền ⇒ không tự ghi nhận (<code>RECON_FAILED</code>) và phải qua CS. Nút &quot;Sao chép&quot; có phản hồi &quot;✓ Đã sao chép&quot; — giảm tối đa lỗi gõ tay. <span class="ref">BR-PAY-04</span> <span class="ref">BR-PAY-01</span> <span class="ref">FR-PAY-03</span></span></li><li><span class="num">13</span><span>SLA xác nhận thủ công: badge <code>wf-sla</code> đổi màu theo thời gian chờ (ok ≤ 1h · soon ≤ 2h · over &gt; 2h kèm câu &quot;quá 2 giờ — gọi 1900-xxx&quot;). Mỗi lần ADMIN xác nhận đều ghi <code>confirmed_by</code> + audit. <span class="ref">BR-PAY-04</span> <span class="ref">BR-ADM-03</span></span></li></ol></div><h2 id="_4-trang-thai-pending-deposit-—-cho-xac-nhan" tabindex="-1">4. Trạng thái PENDING_DEPOSIT — &quot;chờ xác nhận&quot; <a class="header-anchor" href="#_4-trang-thai-pending-deposit-—-cho-xac-nhan" aria-label="Permalink to &quot;4. Trạng thái PENDING_DEPOSIT — &quot;chờ xác nhận&quot;&quot;">​</a></h2><div class="wf"><div class="wf-row" style="align-items:flex-start;"><div class="wf-grow"><div class="wf-card" style="border-width:2px;border-color:var(--wf-warn);"><div class="pad wf-col" style="gap:10px;"><div class="wf-row between middle"><span class="wf-badge warn">PENDING_DEPOSIT — CHỜ GHI NHẬN CỌC</span><span class="wf-sla soon">chờ 00:47 / SLA 2 giờ</span></div><span class="wf-title">Đã đăng ký phiên DGA-2026-0001 — đang chờ xác nhận cọc 90.000.000 ₫</span><div class="wf-feed"><div class="wf-feed-head"><span>DIỄN TIỄN</span><span>Thời điểm</span></div><div class="wf-feed-row"><span><b>Đồng ý quy chế</b> — registration tạo, trạng thái PENDING_DEPOSIT</span><span>10/10/2026 14:02</span></div><div class="wf-feed-row"><span><b>Đã chuyển khoản thủ công</b> · nội dung <code>ANPHUC pay_01J9ZK2M4Q</code> · 90.000.000 ₫</span><span>10/10/2026 14:20</span></div><div class="wf-feed-row system"><span>⏳ Chờ ADMIN đối chiếu nội dung bill + số tiền (mục tiêu ≤ 2 giờ làm việc)</span></div><div class="wf-feed-row"><span class="wf-muted">Xác nhận xong → <b>ACTIVE</b>, cấp bí danh TV-XXXX, mở quyền ra giá</span><span class="wf-muted">—</span></div></div><div class="wf-row between middle"><span class="wf-small">Hạn cuối để cọc được tính: <b>15/10/2026 08:00 (GMT+7)</b> <span class="wf-callout">14</span></span><span class="wf-countdown sm">4 ngày 17:40:12</span></div><div class="wf-row wrap" style="gap:8px;"><span class="wf-btn">Xem lại thông tin bill</span><span class="wf-btn ghost">Đã chuyển mà chưa thấy cập nhật? Gửi CS 1900-xxx</span></div></div></div></div><div style="width:300px;flex:none;" class="wf-col"><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><span class="wf-small wf-strong">TRONG LÚC CHỜ</span><span class="wf-small">· Chưa ra giá được — quyền chỉ mở khi trạng thái ACTIVE.</span><span class="wf-small">· Không cần chuyển thêm lần nữa: chuyển trùng sẽ phải làm thủ tục hoàn, chậm hơn.</span><span class="wf-small">· Trang tự kiểm tra trạng thái mỗi 5 giây khi bạn đang mở.</span><span class="wf-small">· Quá hạn 15/10/2026 08:00 mà cọc chưa được ghi nhận → đăng ký chuyển REJECTED (tự động).</span></div></div><div class="wf-note">Bạn sẽ nhận thông báo trong app + email ngay khi cọc được xác nhận.</div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">14</span><span>Cọc phải ở trạng thái PAID <b>trước</b> hạn đóng đăng ký, nếu không registration bị job chuyển REJECTED. Màn này luôn hiện cả hai đồng hồ: SLA xác nhận (2 giờ) và hạn cuối nghiệp vụ (ngày cụ thể) — user cần biết cái nào mới là cái quyết định. Số lần tạo payment intent trong window không giới hạn (hỏng thì tạo lại). <span class="ref">BR-AU-07</span> <span class="ref">BR-PAY-03</span></span></li><li><span class="num">15</span><span>Trạng thái này <b>không phải lỗi</b>: đừng dùng màu đỏ hay chữ &quot;thất bại&quot;. Nếu ADMIN đánh dấu FAILED → chuyển panel đỏ nêu lý do + nút &quot;Tạo giao dịch mới&quot; (còn kịp hạn) hoặc &quot;Liên hệ CS&quot; (sát hạn). <span class="ref">docs/05 §3 SC-24</span></span></li></ol></div><h2 id="_5-active-—-đa-đu-đieu-kien-tham-gia" tabindex="-1">5. ACTIVE — đã đủ điều kiện tham gia <a class="header-anchor" href="#_5-active-—-đa-đu-đieu-kien-tham-gia" aria-label="Permalink to &quot;5. ACTIVE — đã đủ điều kiện tham gia&quot;">​</a></h2><div class="wf"><div class="wf-col" style="max-width:620px;"><div class="wf-card" style="border-color:var(--wf-ok);border-width:2px;"><div class="pad wf-col" style="gap:10px;"><div class="wf-row between middle"><span class="wf-badge ok">ACTIVE — ĐÃ ĐỦ ĐIỀU KIỆN</span><span class="wf-small wf-ok-text">✓ Cọc 90.000.000 ₫ ghi nhận 10/10/2026 15:04</span></div><span class="wf-title lg">Bí danh của bạn trong phiên: <span class="wf-money lg">TV-7F2A</span></span><span class="wf-text">Mọi lượt ra giá của bạn chỉ hiện dưới bí danh này — không tên thật, không ảnh, không số điện thoại. Người tham gia khác không biết bạn là ai. <span class="wf-callout">16</span></span><div class="wf-row between"><span class="wf-text">Phiên</span><span class="wf-strong">DGA-2026-0001 · căn CT2-A18.05 · NOXH HP-380</span></div><div class="wf-row between"><span class="wf-text">Mở phiên</span><span class="wf-strong">16/10/2026 08:00 (GMT+7)</span></div><div class="wf-row between"><span class="wf-text">Giá khởi điểm · bước giá</span><span class="wf-money">1.800.000.000 ₫ · +18.000.000 ₫</span></div><div class="wf-row between"><span class="wf-text">Mã đăng ký</span><span class="wf-trace">agr_01J9ZK3B7P</span></div><div class="wf-note" style="margin:0;">Nhắc lịch: 24 giờ và 15 phút trước giờ mở phiên (thông báo trong app + email).</div><span class="wf-btn primary lg block">VÀO PHIÊN — SC-06 (mở lúc 16/10/2026 08:00)</span><span class="wf-small wf-center">Trước giờ mở, nút ở trạng thái chờ kèm đồng hồ đếm ngược — không ẩn đi.</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">16</span><span>Bí danh cấp khi registration chuyển ACTIVE, unique trong phiên (<code>TV-XXXX</code>). Hiện to, rõ ngay trên trang này để user nhớ mã của mình khi vào feed — tránh nhầm &quot;giá của người khác&quot; với giá của mình. <span class="ref">BR-AU-20</span> <span class="ref">docs/06 §4.3</span> <span class="ref">FR-NTF-03</span></span></li></ol></div><h2 id="_6-trang-thai-bi-chan-—-đong-đang-ky-410-amp-mat-quyen-403" tabindex="-1">6. Trạng thái bị chặn — đóng đăng ký (410) &amp; mất quyền (403) <a class="header-anchor" href="#_6-trang-thai-bi-chan-—-đong-đang-ky-410-amp-mat-quyen-403" aria-label="Permalink to &quot;6. Trạng thái bị chặn — đóng đăng ký (410) &amp;amp; mất quyền (403)&quot;">​</a></h2><div class="wf"><div class="wf-grid"><div class="wf-col"><span class="wf-state-label">410 — ĐÃ ĐÓNG ĐĂNG KÝ</span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-toast danger">Đã đóng đăng ký (trước giờ mở 24h)</div><span class="wf-small">Đăng ký đóng lúc <b>15/10/2026 08:00 (GMT+7)</b>. Phiên vẫn diễn ra đúng lịch — bạn có thể theo dõi công khai (feed ẩn danh).</span><span class="wf-btn block">Xem các phiên SẮP MỞ còn nhận đăng ký → SC-05</span><span class="wf-small wf-muted">Toàn bộ form cọc/ẩn nút thanh toán; không hiện countdown &quot;đóng đăng ký&quot; nữa mà hiện giờ mở phiên. <span class="wf-callout">17</span></span></div></div></div><div class="wf-col"><span class="wf-state-label">403 — BỊ TẠM NGƯNG QUYỀN ĐẤU GIÁ</span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-toast danger">Tài khoản của bạn đã bị tạm ngưng quyền đấu giá — liên hệ CSKH 1900-xxx để được giải thích</div><span class="wf-small">Áp dụng cho <b>mọi</b> phiên, kể cả phiên đã nộp cọc trước đó. Quyền chỉ được mở lại bởi ADMIN (có ghi lý do + audit).</span><span class="wf-btn block">Gửi yêu cầu xem xét lại</span><span class="wf-small wf-muted">Không đổ lỗi chung chung: nếu lý do là đơn quá hạn cũ, nói rõ &quot;do đơn thanh toán … quá hạn 24 giờ&quot; và link sang SC-25. <span class="wf-callout">18</span></span></div></div></div><div class="wf-col"><span class="wf-state-label">403 — CHƯA XÁC MINH DANH TÍNH</span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-toast warn">Bạn cần xác minh danh tính (CCCD) trước khi thao tác này</div><span class="wf-small">Panel thay cho toàn bộ form đăng ký. Duyệt KYC xong quay lại đúng phiên này (deep-link return).</span><span class="wf-btn primary block">Xác minh danh tính → SC-21</span></div></div></div><div class="wf-col"><span class="wf-state-label">409 — ĐÃ ĐĂNG KÝ RỒI / LÀ CHỦ CĂN NÀY</span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-toast info">Bạn đã có đăng ký cho phiên này</div><span class="wf-small">Không tạo đăng ký thứ hai — hiện thẳng trạng thái hiện có (PENDING_DEPOSIT / ACTIVE) kèm nút đi tiếp tương ứng.</span><span class="wf-small">Nếu bạn là <b>chủ căn hộ</b>: không được đăng ký đấu giá chính căn của mình; màn hình chuyển sang chế độ &quot;theo dõi phiên căn của bạn&quot; (không form cọc). <span class="ref">BR-AU-05</span></span><span class="wf-btn block">Xem trạng thái đăng ký của tôi</span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">17</span><span>Mã lỗi → banner tương ứng, đúng bảng docs/05 §5: <code>AUCTION_REG_CLOSED</code> (410) · <code>AUCTION_PRIVILEGE_SUSPENDED</code> (403) · <code>KYC_REQUIRED</code> (403) · <code>DUPLICATE_REGISTRATION</code> (409). Message hiển thị <b>nguyên văn</b> docs/06 §5. <span class="ref">docs/05 §5</span> <span class="ref">docs/06 §5</span></span></li><li><span class="num">18</span><span>Tạm ngưng quyền không ảnh hưởng đơn thanh toán đã EXPIRED (tiền đã xử lý theo quy chế) — vì vậy panel này không hứa &quot;hoàn cọc&quot;, chỉ dẫn đường khiếu nại qua CS. <span class="ref">BR-AU-16</span> <span class="ref">BR-PAY-06</span></span></li><li><span class="num">19</span><span>Phiên bị ADMIN hủy trước giờ mở: banner trung tính &quot;Phiên đã bị hủy&quot; + hoàn cọc 100% trong 3 ngày làm việc về tài khoản đã nộp, không cần thao tác; tin quay về bán thường (link SC-03). <span class="ref">BR-AU-19</span> <span class="ref">FR-NTF-05</span></span></li></ol></div><h2 id="_7-mobile-360px" tabindex="-1">7. Mobile 360px <a class="header-anchor" href="#_7-mobile-360px" aria-label="Permalink to &quot;7. Mobile 360px&quot;">​</a></h2><div class="wf"><div class="wf-row" style="justify-content:center;gap:20px;flex-wrap:wrap;"><div><span class="wf-state-label">MOBILE — BƯỚC 2 · TIỀN CỌC</span><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-bell">🔔<span class="count">2</span></span></div><div class="wf-container" style="padding:12px;"><div class="wf-steps" style="margin:4px 0 12px;"><span class="wf-step done">1 ✓</span><span class="wf-step active">2 · Cọc</span><span class="wf-step">3 · Kênh</span></div><div class="wf-card flat"><div class="pad wf-col" style="gap:6px;"><span class="wf-small">Phiên <b>DGA-2026-0001</b> · căn CT2-A18.05 · NOXH HP-380</span><div class="wf-row between"><span class="wf-text">Giá khởi điểm</span><span class="wf-money">1.800.000.000 ₫</span></div><div class="wf-row between"><span class="wf-text">Tỷ lệ cọc</span><span class="wf-money">5%</span></div><div class="wf-row between"><span class="wf-text">Mức tối thiểu</span><span class="wf-money">10.000.000 ₫</span></div><div class="wf-row between" style="border-top:2px solid var(--wf-ink);padding-top:6px;"><span class="wf-strong">Bạn chuyển</span><span class="wf-money lg">90.000.000 ₫</span></div></div></div><div class="wf-note">Trúng → trừ vào tiền phải trả · Thua → hoàn 100% trong 3 ngày làm việc · Trúng mà không trả trong 24h → mất cọc</div><div class="wf-col" style="gap:6px;margin-top:10px;"><span class="wf-radio checked">VNPay</span><span class="wf-radio">Chuyển khoản thủ công</span></div></div><div class="wf-col" style="gap:4px;position:sticky;bottom:0;background:#fff;border-top:1px solid var(--wf-line);padding:10px 12px;"><span class="wf-countdown sm">Đóng đăng ký sau 4 ngày 21:18</span><span class="wf-btn primary block">NỘP CỌC 90.000.000 ₫</span></div></div></div><div><span class="wf-state-label">MOBILE — BILL THỦ CÔNG (SAO CHÉP 1 CHẠM)</span><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-badge warn">chờ xác nhận</span></div><div class="wf-container" style="padding:12px;"><span class="wf-small wf-strong">NỘI DUNG CHUYỂN KHOẢN</span><div class="wf-card flat" style="border-color:var(--wf-accent);background:var(--wf-accent-soft);margin-top:6px;"><div class="pad wf-col" style="gap:6px;"><span class="wf-money lg">ANPHUC pay_01J9ZK2M4Q</span><span class="wf-small">Mẫu: <code>ANPHUC &lt;paymentId&gt;</code> — sai nội dung là không ghi nhận cọc</span><span class="wf-btn primary sm block">Sao chép nội dung</span></div></div><div class="wf-row between middle" style="margin-top:10px;"><span class="wf-small">Số tiền</span><span class="wf-money">90.000.000 ₫</span></div><div class="wf-row between middle"><span class="wf-small">Ngân hàng · STK</span><span class="wf-small">[bankName] · [accountNo]</span></div><div class="wf-row between middle"><span class="wf-small">Chủ tài khoản</span><span class="wf-small">[accountName]</span></div><div class="wf-toast ok">✓ Đã sao chép</div><div class="wf-card flat" style="margin-top:8px;"><div class="pad wf-col" style="gap:4px;"><div class="wf-row between middle"><span class="wf-small wf-strong">Trạng thái</span><span class="wf-sla soon">chờ 00:47 / 2 giờ</span></div><span class="wf-small">Chờ ADMIN đối chiếu nội dung + số tiền. Trang tự kiểm tra mỗi 5 giây khi đang mở.</span></div></div><span class="wf-btn block sm" style="margin-top:10px;">Đã chuyển mà chưa cập nhật? Gọi 1900-xxx</span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích mobile</div><ol><li><span class="num">M</span><span>Breakdown cọc <b>giữ đủ từng dòng</b> trên mobile (không gộp) — đây là số tiền lớn, người dùng hay thao tác trên điện thoại. Sidebar phiên chuyển thành 1 dòng tóm tắt đầu trang.</span></li><li><span class="num">M</span><span>Nút nộp cọc dính đáy + dòng &quot;đóng đăng ký sau …&quot; ngay trên nút: quyết định tiền bạc phải thấy hạn ngay tại chỗ bấm. Quy chế modal trên mobile = full-screen sheet, vẫn bắt buộc cuộn hết + tick.</span></li><li><span class="num">M</span><span>Màn bill: mỗi trường một nút &quot;Sao chép&quot; riêng, có phản hồi &quot;✓ Đã sao chép&quot;; nội dung bill đặt trên cùng, chữ to nhất — đây là thứ user phải chép chính xác.</span></li></ol></div><h2 id="_8-bon-trang-thai-nen-cua-man" tabindex="-1">8. Bốn trạng thái nền của màn <a class="header-anchor" href="#_8-bon-trang-thai-nen-cua-man" aria-label="Permalink to &quot;8. Bốn trạng thái nền của màn&quot;">​</a></h2><div class="wf"><div class="wf-grid"><div class="wf-col"><span class="wf-state-label">LOADING</span><div class="wf-col" style="gap:8px;"><div class="wf-skeleton"><div class="wf-lines"><span class="w-40"></span><span class="w-90"></span><span class="w-60"></span></div></div><div class="wf-skeleton"><div class="wf-lines"><span class="w-75"></span><span class="w-50"></span></div></div><span class="wf-small">Skeleton đúng khung 3 bước + panel phải; không hiện form khi chưa có <code>depositAmount</code> từ server.</span></div></div><div class="wf-col"><span class="wf-state-label">EMPTY — CHƯA ĐĂNG KÝ PHIÊN NÀO</span><div class="wf-empty"><span class="icon">⌂</span><span class="wf-title">Bạn chưa đăng ký phiên đấu giá nào</span><div class="wf-text">Phiên sắp mở sẽ hiện ở đây kèm tiền cọc phải nộp và hạn đăng ký.</div><span class="wf-btn primary">Xem phiên sắp mở → SC-05</span></div></div><div class="wf-col"><span class="wf-state-label">ERROR</span><div class="wf-error-box"><span class="wf-title">Không tải được thông tin phiên</span><div class="wf-text" style="margin:6px 0;">Chưa tạo được giao dịch nào — bạn <b>không bị trừ tiền</b>. Thử lại.</div><span class="wf-btn block">Thử lại</span><span class="wf-trace">traceId a1b2c3 — đọc mã này khi gọi CS 1900-xxx</span></div></div><div class="wf-col"><span class="wf-state-label">DATA</span><div class="wf-card"><div class="pad wf-col" style="gap:6px;"><span class="wf-small wf-strong">Mục 1 — trang đăng ký đầy đủ</span><span class="wf-small">Đăng ký hiện có được liệt kê dạng danh sách (mỗi phiên 1 card: trạng thái · cọc · hạn · nút đi tiếp), phiên đang thao tác mở rộng chi tiết.</span><span class="wf-small wf-muted">Tab mặc định: phiên còn thao tác được trước, phiên đã ACTIVE/đã kết thúc sau.</span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">20</span><span>Quy tắc 4 trạng thái áp dụng cho mọi màn dữ liệu. Riêng màn tiền tệ: hộp lỗi phải khẳng định <b>&quot;không bị trừ tiền&quot;</b> khi giao dịch chưa tạo được, vì đó là nỗi lo lớn nhất của user. <span class="ref">docs/05 §1.4</span></span></li></ol></div><h2 id="_9-checklist-designer-khi-dung-figma-cho-sc-24" tabindex="-1">9. Checklist designer khi dựng Figma cho SC-24 <a class="header-anchor" href="#_9-checklist-designer-khi-dung-figma-cho-sc-24" aria-label="Permalink to &quot;9. Checklist designer khi dựng Figma cho SC-24&quot;">​</a></h2><ul><li>[ ] Đủ layout: desktop (3 bước + panel phiên phải) / tablet 768 (panel xuống dưới) / mobile 360 (1 cột + nút dính đáy)</li><li>[ ] Quy chế modal: khung cuộn + % đã đọc + checkbox khóa + nút đồng ý khóa → 2 frame (chưa cuộn / đã cuộn+tick), không tắt bằng click nền</li><li>[ ] Breakdown cọc: 5 dòng (giá khởi điểm · tỷ lệ · tính ra · mức tối thiểu · có áp tối thiểu không) + dòng tổng &quot;Bạn chuyển&quot; — tuyệt đối không gộp</li><li>[ ] Ba kết cục của cọc (trúng / thua / vi phạm 24h) hiện trước khi bấm thanh toán</li><li>[ ] Kênh VNPay: nút redirect + panel chờ poll 5 giây + TTL link 6 giờ</li><li>[ ] Kênh thủ công: bill (bank · STK · chủ TK · số tiền · nội dung <code>ANPHUC &lt;paymentId&gt;</code>) mỗi trường một nút sao chép + phản hồi &quot;✓ Đã sao chép&quot;</li><li>[ ] Trạng thái PENDING_DEPOSIT: timeline diễn tiến + badge SLA (ok/soon/over) + hạn đóng đăng ký + điều không nên làm</li><li>[ ] Trạng thái ACTIVE: bí danh TV-7F2A nổi bật + giờ mở phiên + nhắc lịch 24h/15p</li><li>[ ] Banner chặn: 410 đóng đăng ký · 403 mất quyền · 403 chưa KYC · 409 đã đăng ký / là chủ căn · phiên bị hủy (hoàn cọc)</li><li>[ ] 4 trạng thái nền: skeleton / empty / error (kèm &quot;không bị trừ tiền&quot; + traceId) / data</li><li>[ ] Không emoji làm icon production (🔔/✓/⏳ trong wireframe chỉ là placeholder vị trí)</li><li>[ ] Copy: đúng bảng docs/06 §5; tiền <code>90.000.000 ₫</code>; giờ <code>dd/MM/yyyy HH:mm</code> + &quot;GMT+7&quot;; thông tin bank lấy từ API, không hardcode</li><li>[ ] Accessibility: modal quy chế focus-trap, nội dung cuộn đọc được bằng bàn phím, contrast AA cho badge warn/danger, nút sao chép có aria-live thông báo kết quả</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ cần PM duyệt trên docs/08 trước.</p></div>',30)])])}const w=s(l,[["render",t]]);export{r as __pageData,w as default};
